#!/usr/bin/env python3
"""Identification of the subalgebras found by sweep3.py:
   * decomposition into minimal ideals,
   * decomposition of the even part into simple summands + centre,
   * for a copy of D(2,1;a): the value of the parameter a, read off the
     invariant bilinear form (b_1:b_2:b_3) = (1/c_1 : 1/c_2 : 1/c_3).
"""
from fractions import Fraction as F
from itertools import combinations
from lin import kernel
from sweep3 import Ech, closure, derived, centre_dim, sdim_of, ev


def ideal_generated(g, ub, x):
    """the u-ideal generated by x inside u = span(ub)."""
    E = Ech(g.N, [x])
    items = [list(x)]
    i = 0
    while i < len(items):
        for y in ub:
            v = g.br(y, items[i])
            if any(v) and E.add(v):
                items.append(v)
        i += 1
    return E


def weight_gens(g, ub):
    """generators adapted to the torus t' = u cap t: since every ideal of u is
       t'-invariant, it contains a t'-weight vector, so the ideals generated by
       the t'-weight components of a basis of u already contain every minimal
       ideal.  (Generating from an unadapted basis is WRONG: a generic vector of
       sl(2)+sl(2) generates the whole of it.)"""
    E = Ech(g.N, ub)
    b = E.basis()
    cart = [g.e(i) for i in range(g.N) if all(x == 0 for x in g.WT[i])]
    tin = [x for x in cart if E.contains(x)]
    if not tin:
        return b
    groups = {}
    for i in range(g.N):
        w = []
        for h in tin:
            v = g.br(h, g.e(i))
            c = F(0)
            for k, val in enumerate(v):
                if val:
                    assert k == i
                    c = val
            w.append(c)
        groups.setdefault(tuple(w), []).append(i)
    gens = []
    for w, idx in groups.items():
        ix = set(idx)
        for v in b:
            pv = [x if i in ix else F(0) for i, x in enumerate(v)]
            if any(pv):
                gens.append(pv)
    # every projection lies in u because u is t'-invariant
    for v in gens:
        assert E.contains(v), "u is not t'-invariant"
    return gens + b


def minimal_ideals(g, ub):
    """list of the minimal nonzero ideals of u = span(ub) (as Ech objects)."""
    ids = []
    for x in weight_gens(g, ub):
        I = ideal_generated(g, ub, x)
        if I.dim() == 0:
            continue
        if not any(J.dim() == I.dim() and
                   all(J.contains(v) for v in I.basis()) for J in ids):
            ids.append(I)
    mins = []
    for I in ids:
        if not any(J.dim() < I.dim() and all(I.contains(v) for v in J.basis())
                   for J in ids):
            mins.append(I)
    uniq = []
    for I in mins:
        if not any(J.dim() == I.dim() and
                   all(J.contains(v) for v in I.basis()) for J in uniq):
            uniq.append(I)
    return uniq


def even_part(g, ub):
    E = Ech(g.N, ub)
    out = []
    for v in E.basis():
        if all(x == 0 or g.PAR[i] == 0 for i, x in enumerate(v)):
            out.append(v)
    Eev = Ech(g.N, out)
    return Eev.basis()


def report(g, ub, label=""):
    E = Ech(g.N, ub)
    sd = sdim_of(g, E.basis())
    print("   %s sdim %d|%d  dim %d  derived %s  centre %d"
          % (label, sd[0], sd[1], E.dim(), derived(g, E), centre_dim(g, E)))
    mins = minimal_ideals(g, E.basis())
    tot = Ech(g.N, [v for I in mins for v in I.basis()])
    print("      minimal ideals: %s   (their sum has dim %d of %d)"
          % (", ".join("%d|%d" % sdim_of(g, I.basis()) for I in mins),
             tot.dim(), E.dim()))
    evb = even_part(g, E.basis())
    Eev = Ech(g.N, evb)
    mev = minimal_ideals(g, evb)
    print("      even part dim %d: minimal ideals %s, centre %d"
          % (Eev.dim(), ", ".join(str(I.dim()) for I in mev),
             centre_dim(g, Eev)))
    return mins, mev


# ------------------------------------------------------- the parameter a
def invariant_form(g, ub):
    """the invariant bilinear forms on u = span(ub) (basis of the space)."""
    n = len(ub)
    unk = [(i, j) for i in range(n) for j in range(n)]
    pos = {p: k for k, p in enumerate(unk)}
    rows = []
    # B([x,y],z) = B(x,[y,z])  for all basis triples
    for a in range(n):
        for b in range(n):
            for c in range(n):
                row = [F(0)] * len(unk)
                xy = _coords(g, ub, g.br(ub[a], ub[b]))
                yz = _coords(g, ub, g.br(ub[b], ub[c]))
                if xy is None or yz is None:
                    return None
                for i, cf in enumerate(xy):
                    if cf:
                        row[pos[(i, c)]] += cf
                for i, cf in enumerate(yz):
                    if cf:
                        row[pos[(a, i)]] -= cf
                rows.append(row)
    ker = kernel(rows, len(unk))
    out = []
    for k in ker:
        B = [[k[pos[(i, j)]] for j in range(n)] for i in range(n)]
        out.append(B)
    return out


def _coords(g, ub, v):
    E = Ech(g.N, [])
    # build echelon with recorded combinations
    piv = {}
    combos = {}
    for idx, b in enumerate(ub):
        w = list(b)
        cmb = [F(0)] * len(ub)
        cmb[idx] = F(1)
        for c in sorted(piv):
            if w[c]:
                f = w[c]
                w = [x - f * y for x, y in zip(w, piv[c])]
                cmb = [x - f * y for x, y in zip(cmb, combos[c])]
        for c in range(g.N):
            if w[c]:
                inv = F(1) / w[c]
                piv[c] = [x * inv for x in w]
                combos[c] = [x * inv for x in cmb]
                break
    w = list(v)
    cmb = [F(0)] * len(ub)
    for c in sorted(piv):
        if w[c]:
            f = w[c]
            w = [x - f * y for x, y in zip(w, piv[c])]
            cmb = [x - f * y for x, y in zip(cmb, combos[c])]
    if any(w):
        return None
    return cmb


def sl2_triples(g, ideals):
    """for 3-dimensional ideals: the canonical (E,H,F) with H=[E,F],[H,E]=2E."""
    out = []
    for I in ideals:
        if I.dim() != 3:
            out.append(None)
            continue
        b = I.basis()
        # find H with eigenvalues 2,0,-2 in ad|_I : take any [x,y]
        found = None
        for x, y in combinations(b, 2):
            H = g.br(x, y)
            if not any(H):
                continue
            # ad H on I must have eigenvalues 0, +-2 : test on the basis
            found = (x, y, H)
            break
        out.append(found)
    return out


def d21a_parameter(g, ub):
    """if u = span(ub) is D(2,1;a) (sdim 9|8, three sl(2) ideals in u_ev),
       return the S_3-orbit of a."""
    E = Ech(g.N, ub)
    evb = even_part(g, E.basis())
    mev = minimal_ideals(g, evb)
    if len(mev) != 3 or any(I.dim() != 3 for I in mev):
        return None
    forms = invariant_form(g, E.basis())
    if not forms or len(forms) != 1:
        return None
    B = forms[0]
    ubl = E.basis()
    bs = []
    for I in mev:
        # canonical H: solve for the sl(2) triple inside I
        H = _canonical_H(g, I)
        if H is None:
            return None
        co = _coords(g, ubl, H)
        val = sum(co[i] * B[i][j] * co[j] for i in range(len(co))
                  for j in range(len(co)) if co[i] and co[j])
        bs.append(val)
    if any(x == 0 for x in bs):
        return None
    cs = [F(1) / x for x in bs]
    s = sum(cs)
    if s != 0:
        cs = [c - s / 3 for c in cs]        # normalise c_1+c_2+c_3 = 0
    if cs[0] == 0:
        cs = [cs[1], cs[2], cs[0]]
    a = cs[1] / cs[0]
    orb = sorted({a, 1 / a, -1 - a, F(-1) / (1 + a), -(1 + a) / a,
                  -a / (1 + a)}) if a not in (0, -1) else [a]
    return a, orb, bs


def _canonical_H(g, I):
    """H = [E,F] for an sl(2)-triple in the 3-dimensional simple ideal I."""
    b = I.basis()
    for x in b:
        for y in b:
            H = g.br(x, y)
            if not any(H):
                continue
            # need [H,x] = 2x  (then (x,H,y) is a standard triple up to scale)
            hx = g.br(H, x)
            if hx == [2 * t for t in x]:
                return H
            if hx == [-2 * t for t in x]:
                return [-t for t in H]
    # fall back: scale
    for x in b:
        for y in b:
            H = g.br(x, y)
            if not any(H):
                continue
            hx = g.br(H, x)
            lam = None
            for i in range(g.N):
                if x[i]:
                    lam = hx[i] / x[i]
                    break
            if lam and lam != 0:
                sc = F(2) / lam
                return [t * sc for t in H]
    return None
